     "คุณเป็นคนมีสติในการตัดสินใจ ไม่รีบร้อนเกินไปและไม่ลังเลนานเกินไป",
     "ว่ากันว่าอิ้นตึ๊งที่สมส่วนสะท้อนอารมณ์ที่มั่นคง คุณจึงรับมือกับเรื่องเครียดได้โดยไม่เสียความเป็นตัวเอง",
     "คุณให้ความสำคัญกับทั้งเหตุผลและความรู้สึก เวลาเพื่อนปรึกษา คุณให้คำตอบที่ทั้งใช้ได้จริงและอ่อนโยน"
