     "ในที่ประชุม คุณฟังอย่างตั้งใจก่อนแสดงความเห็น ความเห็นของคุณจึงมักมีน้ำหนักและถูกนำไปใช้จริง",
     "จังหวะการทำงานของคุณสม่ำเสมอ ไม่หักโหมจนหมดแรง และไม่ช้าจนตามไม่ทัน ทีมจึงวางแผนกับคุณได้ง่าย",
