     "ก่อนเริ่มงานแต่ละวัน ลองหายใจลึก ๆ สามครั้งและผ่อนคลายหว่างคิ้ว เป็นเคล็ดเล็ก ๆ ที่ช่วยให้ความคิดปลอดโปร่ง",
