     "จัดกระเป๋าสตางค์ให้เป็นระเบียบ แยกธนบัตรตามมูลค่า ตามความเชื่อช่วยให้ภูเขากลางรับทรัพย์ได้เต็มที่",
     "แบ่งความรับผิดชอบให้คนอื่นบ้าง ภูเขาที่สูงจะมั่นคงยิ่งขึ้นเมื่อมีภูเขาลูกอื่นช่วยโอบอุ้ม"
