     "เมื่อภูเขาเหนือแข็งแรง ภาพรวมคือชีวิตที่ยิ่งเดินไกลยิ่งมั่นคง สิ่งที่คุณสร้างไว้วันนี้จะเป็นรากฐานให้วันข้างหน้า",
     "ในศาสตร์โหงวเฮ้ง ภูเขาเหนือที่อิ่มเต็มบอกถึงคนที่มีบริวารและคนรอบข้างเกื้อหนุน ชีวิตคุณจึงไม่ค่อยต้องเดินลำพัง"
